#! /bin/bash

set -e # Exit on error

function preview_start() {
	local OUTPUT=$1
	echo "<!DOCTYPE html>" > $OUTPUT
	echo "<html>" >> $OUTPUT
	echo "	<head>" >> $OUTPUT
	echo "		<title>$2 preview</title>" >> $OUTPUT
	echo "		<style>html{ font-family: system-ui; } td, th { border: 1px solid; } td { padding: 4px;} tr th { position: sticky; top: 0; background-color: white; } td > div { display: inline-flex; } td > div > div { display: flex; flex-direction: column-reverse; align-items: center; justify-content: center; }</style>" >> $OUTPUT
	echo "		<style>img { width: 5rem; height: 5rem; margin: 2px; white-space: break-spaces; font-size: x-small; text-align: right; } .sm { width: 1rem; height: 1rem; } .md { width: 1.5rem; height: 1.5rem; } .fill { background-color: lightgrey; } a { text-decoration: none; }</style>" >> $OUTPUT
	echo "		<style>td > div > b { writing-mode: sideways-lr; text-orientation: upright; text-align: center; } td > div > img:first-of-type { padding-right: 1rem; }</style>" >> $OUTPUT
	echo "	</head>" >> $OUTPUT
	echo "<body>" >> $OUTPUT
	echo "<p>This is a preview of SVG sprites which are accessed via: #anchor</p>" >> $OUTPUT
	echo >> $OUTPUT
	echo "<table>" >> $OUTPUT
}

function preview_end() {
	local OUTPUT=$1
	echo "</tr>" >> $OUTPUT
	echo "</table>" >> $OUTPUT
	echo >> $OUTPUT
	echo "</body>" >> $OUTPUT
	echo "</html>" >> $OUTPUT
	echo "Generated: $OUTPUT"
}

function icon_start() {
	local OUTPUT=$1
	echo "<svg xmlns=\"http://www.w3.org/2000/svg\">" > $OUTPUT
	echo -n "<defs><style>.icon{display:none}.icon:target{display:inline}</style></defs>" >> $OUTPUT
}

function icon_start_ref() {
	local OUTPUT=$1
	local R=$2
	echo "<svg xmlns=\"http://www.w3.org/2000/svg\">" > $OUTPUT
	echo -n "<defs><style>.icon{display:none}.icon:target{display:inline}#$R{display:inline}#$R:has(~ :target){display:none}</style></defs>" >> $OUTPUT
}

function icon_end() {
	local OUTPUT=$1
	echo >> $OUTPUT
	echo -n '</svg>' >> $OUTPUT
	echo "Generated: $OUTPUT"
}

function css_start() {
	local OUTPUT=$1
	if [ -n "$OUTPUT" ]; then
		echo "/* == Generated by: $(basename -- "$0") == */" > $OUTPUT
	fi
}

function css_line() {
	local OUTPUT=$3
	if [ -n "$OUTPUT" ]; then
		echo "$1" >> $OUTPUT.$2
	fi
}

function css_end() {
	local OUTPUT=$2
	if [ -n "$OUTPUT" ]; then
		cat $OUTPUT.$1 >> $OUTPUT
		rm $OUTPUT.$1
		echo "Generated: $OUTPUT"
	fi
}

function rs_start() {
	local OUTPUT=$1
	if [ -n "$OUTPUT" ]; then
		echo "/* == Generated by: $(basename -- "$0") == */" > $OUTPUT
		echo >> $OUTPUT
		echo "#[non_exhaustive]" >> $OUTPUT
		echo "pub struct Icons;" >> $OUTPUT
		echo >> $OUTPUT
		echo "impl Icons {" >> $OUTPUT
	fi
}

function rs_end() {
	local OUTPUT=$1
	if [ -n "$OUTPUT" ]; then
		echo "}" >> $OUTPUT
		echo "Generated: $OUTPUT"
	fi
}

function rs_line() {
	local OUTPUT=$2
	if [ -n "$OUTPUT" ]; then
		echo "$1" >> $OUTPUT
	fi
}

function process_theme() {
	local OUTPUT_NAME=$2
	local OUTPUT_DIR=$3
	local OUTPUT_CSS=$4
	local OUTPUT_RS=$5

	INDEX=0
	declare -A THEME_NAME_INDEX

	THEME_NAME=()
	THEME_PATH=()
	THEME_REPO=()
	THEME_ACTION=()
	THEME_VERSION=()
	THEME_FALLBACK=()

	SCAN_THEMES=false
	SCAN_ICONS=false

	PREVIEW=${OUTPUT_DIR}${OUTPUT_NAME}.preview.html
	preview_start ${PREVIEW} ${OUTPUT_NAME}

	css_start $OUTPUT_CSS
	rs_start $OUTPUT_RS

	while read -r LINE; do
		#echo $LINE
		if $SCAN_THEMES ; then
			if [[ $LINE == "}" ]]; then
				SCAN_THEMES=false # End of themes section
				
				echo "<tr>" >> ${PREVIEW}
				echo "	<th>Icon Anchor</th>" >> ${PREVIEW}

				for N in ${THEME_NAME[*]} ; do # Start of .svg
					I=${THEME_NAME_INDEX[$N]}
					R=${THEME_FALLBACK[$N]}
					rm -f "${OUTPUT_DIR}${OUTPUT_NAME}-${N}.svg.ref"
					if [ -n "$R" ]; then
						icon_start_ref "${OUTPUT_DIR}${OUTPUT_NAME}-${N}.svg" $R
					else
						icon_start "${OUTPUT_DIR}${OUTPUT_NAME}-${N}.svg"
					fi
					echo "	<th>${OUTPUT_NAME}-${THEME_NAME[$I]}.svg (${THEME_VERSION[$I]})<a href='${THEME_REPO[$I]}' target='_blank'> &#128279;</a></th>" >> ${PREVIEW}
				done
				
				echo "</tr>" >> ${PREVIEW}

			elif [[ $LINE == *": {" ]]; then
				THEME_NAME+=(${LINE:1:-4}) # Found theme name
				THEME_NAME_INDEX[${LINE:1:-4}]="$INDEX"
				INDEX=$((INDEX + 1))
				css_line "@container style(--icon-theme: ${LINE:1:-4}) {" ${LINE:1:-4} $OUTPUT_CSS

			elif [[ $LINE == "\"path\": "* ]]; then
				THEME_PATH+=(${LINE:9:-2}) # Found theme path
				cd ../${LINE:9:-2}
				THEME_VERSION+=($(git describe --exact-match --tags 2>/dev/null || true))
				cd - > /dev/null

			elif [[ $LINE == "\"repo\": "* ]]; then
				THEME_REPO+=(${LINE:9:-2}) # Found theme repository

			elif [[ $LINE == "\"action\": "* ]]; then
				THEME_ACTION+=(${LINE:11:-1}) # Found theme viewBox

			elif [[ $LINE == "\"fallback\": "* ]]; then
				THEME_FALLBACK+=(${LINE:13:-1}) # Found fallback sprite definition
			fi

		elif $SCAN_ICONS ; then
			if [[ $LINE == "}" ]]; then
				SCAN_ICONS=false # End of icons section

				for N in ${THEME_NAME[*]} ; do # End of .svg
					I=${THEME_NAME_INDEX[$N]}
					local FILE="${OUTPUT_DIR}${OUTPUT_NAME}-${N}.svg"
					icon_end "$FILE"
					local REF="${FILE}.ref"
					if [ -e "$REF" ]; then
						sed -i "3i <defs>" $FILE
						sed -i "4i $(cat $REF)" $FILE
						sed -i "5i </defs>" $FILE
						rm $REF
					fi
					css_line "}" $N $OUTPUT_CSS
					css_end $N $OUTPUT_CSS
				done

			elif [[ $LINE == *": {" ]]; then
				ICON_NAME=${LINE:1:-4} # Start of current icon

				echo "<tr>" >> ${PREVIEW}
				echo "	<td>$ICON_NAME</td>" >> ${PREVIEW}

				local INAME=${ICON_NAME^^} # To uppercase
				INAME=${INAME//-/_}        # Replace - with _
				rs_line "    pub const ${INAME}: &str = \"${ICON_NAME} \";" $OUTPUT_RS

			elif [[ $LINE == *"},"* ]]; then
				echo "</tr>" >> ${PREVIEW}
				continue

			else
				# Add id and class to inner svg
				THEME=`echo "$LINE" | cut -d '"' -f 2`
				ICON_PATH=`echo "$LINE" | cut -d '"' -f 4`
				I=${THEME_NAME_INDEX[$THEME]} # Get icon them index from name
				N=${THEME_NAME[${I}]}

				# After: id="anchor" class="icon" viewBox
				# First occurrence only
				FIND="<svg"
				REPLACE="$FIND id=\"$ICON_NAME\" class=\"icon\" "

				echo "Processing: $1 $ICON_NAME $N"
				# If icon path starts with # then as <use/>
				# if icon path starts with [#] the add as reference and <use/>
				WRITE_FILE=${OUTPUT_DIR}${OUTPUT_NAME}-${N}.svg
				local FILE_IS_REF=false
				local ICON_NAME_TMP=$ICON_NAME
				if [[ $ICON_PATH == "[#]"* ]]; then
					local ICON_NAME_TMP="_$ICON_NAME"
					local FILE_IS_REF=true
					ICON_PATH=${ICON_PATH:3} # Remove [#]
					echo >> $WRITE_FILE
					echo -n "<use id=\"$ICON_NAME\" class=\"icon\" href=\"#${ICON_NAME_TMP}\"/>" >> $WRITE_FILE
					WRITE_FILE="${WRITE_FILE}.ref"
					REPLACE="$FIND id=\"$ICON_NAME_TMP\" "
				else
					echo >> $WRITE_FILE # Add new line
				fi

				if [[ $ICON_PATH == "#"* ]]; then
					echo -n "<use id=\"$ICON_NAME\" class=\"icon\" href=\"#_${ICON_PATH:1}\"/>" >> $WRITE_FILE
				else
					SVG=$(SVGO_PREFIX=$ICON_NAME svgo "../${THEME_PATH[$I]}$ICON_PATH" -o -)  # Uses config file: svgo.config.mjs
					echo "$SVG" | tr -d '\n'                                                 `# Remove new lines` \
						| sed -e "s/$FIND/$REPLACE/g"                                        `# Add icon class` \
						| tr -s " " >> "${WRITE_FILE}"                                       `# Remove whitespace`
				fi

				echo "	<td>" >> ${PREVIEW}
				echo "		<div>" >> ${PREVIEW}
				if [[ $ICON_PATH == "#"* ]]; then
					echo "			<b>Original</b>" >> ${PREVIEW}
					echo "			<img alt='Missing as uses reference to: #${ICON_PATH:1}'>" >> ${PREVIEW}
				else
					echo "			<b>Original</b>" >> ${PREVIEW}
					echo "			<img alt='git submodule missing' src='../${THEME_PATH[$I]}$ICON_PATH'>" >> ${PREVIEW}
				fi
				echo "			<b>Sprites</b>" >> ${PREVIEW}
				echo "			<img src='./${OUTPUT_NAME}-${N}.svg#$ICON_NAME'>" >> ${PREVIEW}
				echo "			<div>" >> ${PREVIEW}
				echo "				<img class='md' src='./${OUTPUT_NAME}-${N}.svg#$ICON_NAME'>" >> ${PREVIEW}
				echo "				<img class='sm' src='./${OUTPUT_NAME}-${N}.svg#$ICON_NAME'>" >> ${PREVIEW}
				echo "			</div>" >> ${PREVIEW}
				echo "			<img class='fill' src='./${OUTPUT_NAME}-${N}.svg#$ICON_NAME'>" >> ${PREVIEW}
				echo "			<div>" >> ${PREVIEW}
				echo "				<img class='fill md' src='./${OUTPUT_NAME}-${N}.svg#$ICON_NAME'>" >> ${PREVIEW}
				echo "				<img class='fill sm' src='./${OUTPUT_NAME}-${N}.svg#$ICON_NAME'>" >> ${PREVIEW}
				echo "			</div>" >> ${PREVIEW}
				echo "		</div>" >> ${PREVIEW}
				echo "	</td>" >> ${PREVIEW}

				css_line "	.icon.$ICON_NAME {" $N $OUTPUT_CSS
				css_line "		mask-image: url(/assets/icons-$N.svg#$ICON_NAME);" $N $OUTPUT_CSS
				css_line "	}" $N $OUTPUT_CSS
			fi

		else
			if [[ $LINE == "\"themes\": {" ]]; then
				SCAN_THEMES=true
				SCAN_ICONS=false
			elif [[ $LINE == "\"icons\": {" ]]; then
				SCAN_ICONS=true
				SCAN_THEMES=false
			fi
		fi
	done < "$1"

	rs_end $OUTPUT_RS
	preview_end ${PREVIEW}
}

cd "$(dirname "$0")" # cd to this script dir

if ! command -v svgo >/dev/null 2>&1; then
    echo "Not found: svgo"
	if ! command -v npm >/dev/null 2>&1; then
		echo "First install npm, then run: npm install -g svgo"
	else
		echo "Install via: npm install -g svgo"
	fi
	echo "https://github.com/svg/svgo#installation"
    exit 1
fi

git submodule update --progress --init --recursive

process_theme "icons.json" "icons" "../assets/" "../assets/css/icons.css" "../src/frontend/icons.rs"
process_theme "logos.json" "logos" "../assets/"
process_theme "files.json" "files" "../assets/"
